/*
 * test_edr.c
 * Host-only contract checks. Expected packets originate in vectors.json;
 * no expected wire byte is generated by the production codec.
 */

#include "edr.h"

#include <inttypes.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

#define EDR_TEST_ARRAY_SIZE(array) (sizeof(array) / sizeof((array)[0]))
#define EDR_TEST_CHECK(expression) \
    edr_test_check((expression), #expression, __LINE__)

typedef struct
{
    const char *p_name;
    bool b_valid;
    uint8_t source;
    uint8_t kind;
    size_t size;
    uint8_t packet[257];
    uint16_t motor;
    uint8_t faults;
    uint32_t command_ms;
    uint32_t left_counts;
    uint32_t right_counts;
    uint32_t sampled_ms;
    uint8_t flags;
} edr_test_packet_t;

typedef struct
{
    uint32_t current;
    uint32_t previous;
    bool b_valid;
    int32_t delta;
} edr_test_delta_t;

typedef struct
{
    uint32_t now_ms;
    uint32_t sampled_ms;
    uint32_t maximum_ms;
    bool b_fresh;
} edr_test_age_t;

#include "edr_test_vectors.h"

static unsigned int g_edr_test_failures = 0U;
static unsigned long g_edr_test_checks = 0UL;
static volatile uint32_t g_edr_test_checksum = UINT32_C(0);

static void edr_test_check(bool b_condition, const char *p_expression,
                           unsigned int line)
{
    g_edr_test_checks++;
    if (!b_condition)
    {
        (void)fprintf(stderr, "line %u: %s\n", line, p_expression);
        g_edr_test_failures++;
    }
}

static bool edr_test_decode(const uint8_t *p_packet, size_t size)
{
    edr_frame_t frame = {0};
    edr_motion_t motion = {0};
    edr_encoder_t encoder = {0};
    bool b_valid = edr_frame_decode(p_packet, size, &frame);

    if (b_valid && (EDR_SOURCE_MOTOR == frame.source))
    {
        if (EDR_KIND_MOTION == frame.kind)
        {
            b_valid = edr_motion_decode(frame.p_payload, frame.payload_size,
                                       &motion);
        }
        else if (EDR_KIND_ENCODER == frame.kind)
        {
            b_valid = edr_encoder_decode(frame.p_payload, frame.payload_size,
                                        &encoder);
        }
        else
        {
            /* Future owner-defined kinds retain opaque payloads. */
        }
    }
    return b_valid;
}

static void edr_test_known_vectors(void)
{
    size_t index;

    for (index = 0U; index < EDR_TEST_ARRAY_SIZE(g_edr_test_packets); index++)
    {
        const edr_test_packet_t *p_vector = &g_edr_test_packets[index];
        edr_frame_t frame = {0};
        uint8_t payload[EDR_ENCODER_SIZE] = {0};
        uint8_t packet[257] = {0};
        const uint8_t *p_encoded = &p_vector->packet[EDR_HEADER_SIZE];
        size_t encoded_size = 0U;

        if (p_vector->b_valid != edr_test_decode(p_vector->packet, p_vector->size))
        {
            (void)fprintf(stderr, "vector: %s\n", p_vector->p_name);
            EDR_TEST_CHECK(false);
        }
        else
        {
            EDR_TEST_CHECK(true);
        }
        if (p_vector->b_valid)
        {
            EDR_TEST_CHECK(edr_frame_decode(p_vector->packet, p_vector->size,
                                           &frame));
            EDR_TEST_CHECK(p_vector->source == frame.source);
            EDR_TEST_CHECK(p_vector->kind == frame.kind);
            if ((EDR_SOURCE_MOTOR == frame.source) &&
                (EDR_KIND_MOTION == frame.kind))
            {
                edr_motion_t motion = {0};
                edr_motion_t expected = {p_vector->motor, p_vector->faults,
                                         p_vector->command_ms};

                EDR_TEST_CHECK(edr_motion_decode(frame.p_payload,
                                                frame.payload_size, &motion));
                EDR_TEST_CHECK(expected.motor == motion.motor);
                EDR_TEST_CHECK(expected.faults == motion.faults);
                EDR_TEST_CHECK(expected.command_ms == motion.command_ms);
                EDR_TEST_CHECK(edr_motion_encode(&expected, payload,
                                                sizeof(payload)));
                p_encoded = payload;
            }
            else if ((EDR_SOURCE_MOTOR == frame.source) &&
                     (EDR_KIND_ENCODER == frame.kind))
            {
                edr_encoder_t encoder = {0};
                edr_encoder_t expected = {p_vector->left_counts,
                                          p_vector->right_counts,
                                          p_vector->sampled_ms, p_vector->flags};

                EDR_TEST_CHECK(edr_encoder_decode(frame.p_payload,
                                                 frame.payload_size, &encoder));
                EDR_TEST_CHECK(expected.left_counts == encoder.left_counts);
                EDR_TEST_CHECK(expected.right_counts == encoder.right_counts);
                EDR_TEST_CHECK(expected.sampled_ms == encoder.sampled_ms);
                EDR_TEST_CHECK(expected.flags == encoder.flags);
                EDR_TEST_CHECK(edr_encoder_encode(&expected, payload,
                                                 sizeof(payload)));
                p_encoded = payload;
            }
            else
            {
                /* Generic buddies verify the common envelope independently. */
            }
            EDR_TEST_CHECK(edr_frame_encode(p_vector->source, p_vector->kind,
                                           p_encoded, frame.payload_size,
                                           packet, sizeof(packet), &encoded_size));
            EDR_TEST_CHECK(p_vector->size == encoded_size);
            EDR_TEST_CHECK(0 == memcmp(packet, p_vector->packet, p_vector->size));
        }
    }
}

static void edr_test_motor_words(void)
{
    uint32_t value;
    unsigned int valid_count = 0U;

    for (value = 0U; value <= UINT16_MAX; value++)
    {
        uint8_t command = 250U;
        uint8_t power = 251U;
        uint8_t state = 252U;
        /* Integer divisions are independent of the codec's extraction masks. */
        bool b_expected = (value < 4096U) && ((value % 8U) < 7U) &&
                          (((value / 8U) % 128U) < 101U) &&
                          (((value / 1024U) % 4U) < 3U);
        /* Loop bound proves the narrowing conversion fits uint16_t. */
        bool b_valid = edr_motor_unpack((uint16_t)value, &command, &power, &state);

        EDR_TEST_CHECK(b_expected == b_valid);
        if (b_valid)
        {
            uint16_t packed = UINT16_MAX;

            EDR_TEST_CHECK((value % 8U) == command);
            EDR_TEST_CHECK(((value / 8U) % 128U) == power);
            EDR_TEST_CHECK(((value / 1024U) % 4U) == state);
            EDR_TEST_CHECK(edr_motor_pack(command, power, state, &packed));
            EDR_TEST_CHECK(value == packed);
            valid_count++;
        }
        else
        {
            EDR_TEST_CHECK((250U == command) && (251U == power) && (252U == state));
        }
    }
    EDR_TEST_CHECK(2121U == valid_count);

    for (value = 0U; value <= UINT8_MAX; value++)
    {
        uint16_t packed = UINT16_MAX;
        /* Loop bound proves each narrowing conversion fits uint8_t. */
        uint8_t field = (uint8_t)value;
        bool b_command = edr_motor_pack(field, 0U, 0U, &packed);

        EDR_TEST_CHECK((value <= 6U) == b_command);
        if (!b_command)
        {
            EDR_TEST_CHECK(UINT16_MAX == packed);
        }
        packed = UINT16_MAX;
        EDR_TEST_CHECK((value <= 100U) == edr_motor_pack(0U, field, 0U, &packed));
        if (value > 100U)
        {
            EDR_TEST_CHECK(UINT16_MAX == packed);
        }
        packed = UINT16_MAX;
        EDR_TEST_CHECK((value <= 2U) == edr_motor_pack(0U, 0U, field, &packed));
        if (value > 2U)
        {
            EDR_TEST_CHECK(UINT16_MAX == packed);
        }
    }
}

static void edr_test_headers_and_lengths(void)
{
    unsigned int header;
    size_t size;
    uint8_t payload[256] = {0};
    uint8_t packet[258] = {0};
    edr_frame_t frame = {0};

    for (header = 0U; header <= UINT8_MAX; header++)
    {
        bool b_expected = ((header / 64U) == 1U) &&
                          ((header % 8U) >= 1U) && ((header % 8U) <= 5U);

        /* Loop bound proves header fits the single header byte. */
        packet[0] = (uint8_t)header;
        packet[1] = 0U;
        EDR_TEST_CHECK(b_expected == edr_frame_decode(packet, 2U, &frame));
    }
    for (size = 0U; size <= EDR_PAYLOAD_MAX; size++)
    {
        size_t packet_size = 999U;
        size_t index;

        for (index = 0U; index < size; index++)
        {
            /* Payload length limits the index to one byte. */
            payload[index] = (uint8_t)index;
        }
        EDR_TEST_CHECK(edr_frame_encode(1U, 7U, payload, size, packet,
                                       sizeof(packet), &packet_size));
        EDR_TEST_CHECK((size + EDR_HEADER_SIZE) == packet_size);
        EDR_TEST_CHECK(edr_frame_decode(packet, packet_size, &frame));
        EDR_TEST_CHECK(size == frame.payload_size);
        EDR_TEST_CHECK(0 == memcmp(payload, frame.p_payload, size));
        EDR_TEST_CHECK(!edr_frame_decode(packet, packet_size - 1U, &frame));
        EDR_TEST_CHECK(!edr_frame_decode(packet, packet_size + 1U, &frame));
    }
    (void)memset(payload, 0, sizeof(payload));
    for (size = 0U; size <= EDR_PAYLOAD_MAX; size++)
    {
        edr_motion_t motion = {0};
        edr_encoder_t encoder = {0};

        EDR_TEST_CHECK((EDR_MOTION_SIZE == size) ==
                       edr_motion_decode(payload, size, &motion));
        EDR_TEST_CHECK((EDR_ENCODER_SIZE == size) ==
                       edr_encoder_decode(payload, size, &encoder));
    }
    for (header = 0U; header <= UINT8_MAX; header++)
    {
        size_t packet_size = 999U;
        /* Loop bound proves source/kind candidates fit uint8_t. */
        uint8_t candidate = (uint8_t)header;

        EDR_TEST_CHECK(((header >= 1U) && (header <= 5U)) ==
                       edr_frame_encode(candidate, 0U, NULL, 0U, packet,
                                        sizeof(packet), &packet_size));
        EDR_TEST_CHECK((header <= 7U) ==
                       edr_frame_encode(1U, candidate, NULL, 0U, packet,
                                        sizeof(packet), &packet_size));
    }
}

static void edr_test_all_buddy_envelopes(void)
{
    unsigned int source;
    unsigned int kind;
    size_t size;
    uint8_t payload[EDR_PAYLOAD_MAX];
    uint8_t packet[EDR_HEADER_SIZE + EDR_PAYLOAD_MAX + 1U];

    for (source = 1U; source <= 5U; source++)
    {
        for (kind = 0U; kind <= 7U; kind++)
        {
            for (size = 0U; size <= EDR_PAYLOAD_MAX; size++)
            {
                edr_frame_t frame = {0};
                size_t packet_size = 999U;
                size_t index;
                bool b_decoded;
                const uint8_t *p_payload = (0U == size) ? NULL : payload;

                for (index = 0U; index < size; index++)
                {
                    /* Bounded remainder proves the byte conversion fits. */
                    payload[index] = (0U == (index % 3U)) ? 0U :
                        (uint8_t)((index * 37U + size + source + kind) % 256U);
                }
                (void)memset(packet, 0xa5, sizeof(packet));
                /* Loop bounds prove source and kind each fit one byte. */
                EDR_TEST_CHECK(edr_frame_encode((uint8_t)source, (uint8_t)kind,
                                               p_payload, size, packet,
                                               sizeof(packet), &packet_size));
                EDR_TEST_CHECK((size + 2U) == packet_size);
                /* Literal v1 arithmetic is independent of codec masks. */
                EDR_TEST_CHECK((64U + kind * 8U + source) == packet[0]);
                EDR_TEST_CHECK(size == packet[1]);
                EDR_TEST_CHECK(0 == memcmp(payload, &packet[2], size));
                EDR_TEST_CHECK(0xa5U == packet[size + 2U]);
                b_decoded = edr_frame_decode(packet, size + 2U, &frame);
                EDR_TEST_CHECK(b_decoded);
                if (b_decoded)
                {
                    EDR_TEST_CHECK(source == frame.source);
                    EDR_TEST_CHECK(kind == frame.kind);
                    EDR_TEST_CHECK(size == frame.payload_size);
                    EDR_TEST_CHECK(&packet[2] == frame.p_payload);
                    if (&packet[2] == frame.p_payload)
                    {
                        EDR_TEST_CHECK(0 == memcmp(payload, frame.p_payload,
                                                  size));
                    }
                }
            }
        }
    }
}

static void edr_test_reserved_and_canonical_fields(void)
{
    unsigned int field;

    for (field = 0U; field <= UINT8_MAX; field++)
    {
        edr_motion_t motion = {0};
        edr_motion_t decoded_motion = {0};
        edr_encoder_t encoder = {0};
        edr_encoder_t decoded_encoder = {0};
        uint8_t payload[EDR_ENCODER_SIZE] = {0};
        bool b_encoder_valid = (0U == field) ||
                               ((field < 32U) && (0U != (field % 2U)));

        /* Loop bound proves faults/flags fit their destination byte. */
        motion.faults = (uint8_t)field;
        EDR_TEST_CHECK((field < 128U) ==
                       edr_motion_encode(&motion, payload, sizeof(payload)));
        payload[2] = (uint8_t)field;
        EDR_TEST_CHECK((field < 128U) ==
                       edr_motion_decode(payload, EDR_MOTION_SIZE,
                                         &decoded_motion));
        (void)memset(payload, 0, sizeof(payload));
        encoder.flags = (uint8_t)field;
        EDR_TEST_CHECK(b_encoder_valid ==
                       edr_encoder_encode(&encoder, payload, sizeof(payload)));
        payload[12] = (uint8_t)field;
        EDR_TEST_CHECK(b_encoder_valid ==
                       edr_encoder_decode(payload, sizeof(payload),
                                          &decoded_encoder));
    }
}

static void edr_test_failure_outputs_and_nulls(void)
{
    uint8_t payload[EDR_ENCODER_SIZE];
    uint8_t packet[32];
    edr_motion_t motion = {0};
    edr_encoder_t encoder = {0};
    edr_frame_t frame = {0};
    uint16_t word = 123U;
    uint8_t command = 1U;
    uint8_t power = 2U;
    uint8_t state = 3U;
    int32_t delta = INT32_C(42);
    size_t size;

    for (size = 0U; size < EDR_MOTION_SIZE; size++)
    {
        (void)memset(payload, 0xa5, sizeof(payload));
        EDR_TEST_CHECK(!edr_motion_encode(&motion, payload, size));
        EDR_TEST_CHECK(0xa5U == payload[0]);
        motion.motor = 77U;
        EDR_TEST_CHECK(!edr_motion_decode(payload, size, &motion));
        EDR_TEST_CHECK(77U == motion.motor);
        motion.motor = 0U;
    }
    for (size = 0U; size < EDR_ENCODER_SIZE; size++)
    {
        (void)memset(payload, 0xa5, sizeof(payload));
        EDR_TEST_CHECK(!edr_encoder_encode(&encoder, payload, size));
        EDR_TEST_CHECK(0xa5U == payload[0]);
        encoder.left_counts = UINT32_C(123);
        EDR_TEST_CHECK(!edr_encoder_decode(payload, size, &encoder));
        EDR_TEST_CHECK(UINT32_C(123) == encoder.left_counts);
        encoder.left_counts = 0U;
    }
    for (size = 0U; size < (EDR_HEADER_SIZE + EDR_ENCODER_SIZE); size++)
    {
        size_t packet_size = 999U;

        (void)memset(packet, 0xa5, sizeof(packet));
        EDR_TEST_CHECK(!edr_frame_encode(2U, 1U, payload, sizeof(payload),
                                        packet, size, &packet_size));
        EDR_TEST_CHECK(999U == packet_size);
        EDR_TEST_CHECK(0xa5U == packet[0]);
    }
    EDR_TEST_CHECK(!edr_motor_pack(0U, 0U, 0U, NULL));
    EDR_TEST_CHECK(!edr_motor_unpack(0U, NULL, &power, &state));
    EDR_TEST_CHECK(!edr_motor_unpack(0U, &command, NULL, &state));
    EDR_TEST_CHECK(!edr_motor_unpack(0U, &command, &power, NULL));
    EDR_TEST_CHECK((1U == command) && (2U == power) && (3U == state));
    EDR_TEST_CHECK(!edr_motor_pack(7U, 0U, 0U, &word));
    EDR_TEST_CHECK(123U == word);
    EDR_TEST_CHECK(!edr_motion_encode(NULL, payload, sizeof(payload)));
    EDR_TEST_CHECK(!edr_motion_encode(&motion, NULL, sizeof(payload)));
    EDR_TEST_CHECK(!edr_motion_decode(NULL, EDR_MOTION_SIZE, &motion));
    EDR_TEST_CHECK(!edr_motion_decode(payload, EDR_MOTION_SIZE, NULL));
    EDR_TEST_CHECK(!edr_encoder_encode(NULL, payload, sizeof(payload)));
    EDR_TEST_CHECK(!edr_encoder_encode(&encoder, NULL, sizeof(payload)));
    EDR_TEST_CHECK(!edr_encoder_decode(NULL, EDR_ENCODER_SIZE, &encoder));
    EDR_TEST_CHECK(!edr_encoder_decode(payload, EDR_ENCODER_SIZE, NULL));
    EDR_TEST_CHECK(!edr_frame_decode(NULL, 2U, &frame));
    EDR_TEST_CHECK(!edr_frame_decode(packet, 2U, NULL));
    EDR_TEST_CHECK(!edr_frame_encode(1U, 0U, NULL, 1U, packet, sizeof(packet), &size));
    EDR_TEST_CHECK(!edr_frame_encode(1U, 0U, payload, 256U, packet, sizeof(packet), &size));
    EDR_TEST_CHECK(!edr_frame_encode(1U, 0U, payload, SIZE_MAX, packet, sizeof(packet), &size));
    EDR_TEST_CHECK(!edr_frame_encode(1U, 0U, NULL, 0U, NULL, sizeof(packet), &size));
    EDR_TEST_CHECK(!edr_frame_encode(1U, 0U, NULL, 0U, packet, sizeof(packet), NULL));
    frame.source = 123U;
    packet[0] = 0U;
    packet[1] = 0U;
    EDR_TEST_CHECK(!edr_frame_decode(packet, 2U, &frame));
    EDR_TEST_CHECK(123U == frame.source);
    (void)memset(payload, 0, sizeof(payload));
    payload[0] = 1U;
    encoder.left_counts = 456U;
    EDR_TEST_CHECK(!edr_encoder_decode(payload, EDR_ENCODER_SIZE, &encoder));
    EDR_TEST_CHECK(456U == encoder.left_counts);
    payload[1] = 0x10U;
    motion.motor = 77U;
    EDR_TEST_CHECK(!edr_motion_decode(payload, EDR_MOTION_SIZE, &motion));
    EDR_TEST_CHECK(77U == motion.motor);
    EDR_TEST_CHECK(!edr_count_delta(0U, 0U, NULL));
    EDR_TEST_CHECK(!edr_count_delta(UINT32_C(0x80000000), 0U, &delta));
    EDR_TEST_CHECK(INT32_C(42) == delta);
}

static void edr_test_modular_arithmetic(void)
{
    size_t index;

    for (index = 0U; index < EDR_TEST_ARRAY_SIZE(g_edr_test_deltas); index++)
    {
        const edr_test_delta_t *p_vector = &g_edr_test_deltas[index];
        int32_t delta = INT32_C(42);

        EDR_TEST_CHECK(p_vector->b_valid ==
                       edr_count_delta(p_vector->current, p_vector->previous, &delta));
        if (p_vector->b_valid)
        {
            EDR_TEST_CHECK(p_vector->delta == delta);
        }
        else
        {
            EDR_TEST_CHECK(INT32_C(42) == delta);
        }
    }
    for (index = 0U; index < EDR_TEST_ARRAY_SIZE(g_edr_test_ages); index++)
    {
        const edr_test_age_t *p_vector = &g_edr_test_ages[index];

        EDR_TEST_CHECK(p_vector->b_fresh ==
                       edr_age_is_fresh(p_vector->now_ms, p_vector->sampled_ms,
                                        p_vector->maximum_ms));
    }
}

static void edr_test_report_host_measurements(void)
{
    const uint32_t iterations = UINT32_C(1000000);
    edr_encoder_t input = {UINT32_MAX, UINT32_C(123), UINT32_C(456), 31U};
    edr_encoder_t output = {0};
    uint8_t payload[EDR_ENCODER_SIZE];
    clock_t started = clock();
    clock_t stopped;
    uint32_t index;

    for (index = 0U; index < iterations; index++)
    {
        input.sampled_ms = index;
        if (edr_encoder_encode(&input, payload, sizeof(payload)) &&
            edr_encoder_decode(payload, sizeof(payload), &output))
        {
            g_edr_test_checksum = g_edr_test_checksum ^ output.sampled_ms;
        }
    }
    stopped = clock();
    (void)printf("Wire bytes: motion payload=%u packet=%u; encoder payload=%u packet=%u\n",
                 EDR_MOTION_SIZE, EDR_HEADER_SIZE + EDR_MOTION_SIZE,
                 EDR_ENCODER_SIZE, EDR_HEADER_SIZE + EDR_ENCODER_SIZE);
    (void)printf("Host transient DTO sizeof: motion=%zu encoder=%zu frame=%zu (ABI-specific)\n",
                 sizeof(edr_motion_t), sizeof(edr_encoder_t), sizeof(edr_frame_t));
    if (((clock_t)-1 != started) && ((clock_t)-1 != stopped) && (stopped > started))
    {
        double seconds = (double)(stopped - started) / (double)CLOCKS_PER_SEC;

        (void)printf("Host-only encoder encode+decode: %.1f ns/pair; %" PRIu32
                     " iterations; checksum=%" PRIu32 "\n",
                     seconds * 1.0e9 / (double)iterations, iterations,
                     g_edr_test_checksum);
    }
    else
    {
        (void)printf("Host clock resolution did not support a timing estimate.\n");
    }
    (void)printf("Timing excludes hardware, RTOS locking, MQTT and transport; not an RP2040 result.\n");
}

int main(void)
{
    edr_test_known_vectors();
    edr_test_motor_words();
    edr_test_headers_and_lengths();
    edr_test_all_buddy_envelopes();
    edr_test_reserved_and_canonical_fields();
    edr_test_failure_outputs_and_nulls();
    edr_test_modular_arithmetic();
    edr_test_report_host_measurements();
    (void)printf("C checks: %lu; failures: %u\n", g_edr_test_checks,
                 g_edr_test_failures);
    return (0U == g_edr_test_failures) ? 0 : 1;
}

